/**
 * Is the renormalisation generated by a finite grammar?
 *
 * Every arc of a level-n supertile (a strand from one outline crossing to
 * another) is a chain of its children's arcs. Its depth-j signature is the
 * supertile type plus, for each child arc in order, the child's slot and that
 * arc's depth-(j - 1) signature (depth 0: just the supertile type), taken in
 * the arc's canonical direction. If, for each j, the number of distinct
 * signatures among the arcs stops growing as n rises, the arcs fall into
 * finitely many kinds that rewrite into each other the same way at every
 * scale: a finite grammar, from which lengths at any level are matrix powers
 * and the limit shapes are the attractors of a finite family of maps.
 *
 * Usage: tsx arc-grammar.ts <family> <rule> <combo> <maxLevel> [maxDepth] [minLength]
 */
import type { TileFamilyId } from '../src/core';
import { CircuitShapes } from './circuit-shapes';

export function arcSignatureCounts(cs: CircuitShapes, maxDepth: number, minLength: number, collapse = false) {
  const ids: Map<string, number>[] = Array.from({ length: maxDepth + 1 }, () => new Map());
  const intern = (j: number, s: string) => {
    const m = ids[j];
    let v = m.get(s);
    if (v === undefined) {
      v = m.size;
      m.set(s, v);
    }
    return v;
  };
  // prevSig[type][j][k]: directed signature id of the arc leaving outline crossing k, at level n - 1.
  let prev: Record<string, Int32Array[]> = {};
  const rows: { level: number; counts: number[]; arcs: number }[] = [];
  for (let n = 0; n < cs.levels.length; n++) {
    const layer = cs.levels[n];
    const next: Record<string, Int32Array[]> = {};
    const counts = new Array<Set<number>>(maxDepth + 1).fill(null as never).map(() => new Set<number>());
    let arcs = 0;
    for (const [t, L] of Object.entries(layer)) {
      const nk = L.size;
      const sig = Array.from({ length: maxDepth + 1 }, () => new Int32Array(nk).fill(-1));
      for (const k of L.crossings()) {
        if (L.mate(k) < 0) continue;
        sig[0][k] = intern(0, t);
      }
      if (n > 0) {
        for (const k of L.crossings()) {
          if (L.mate(k) < 0) continue;
          const st = cs.enters(n, t, k);
          for (let j = 1; j <= maxDepth; j++) {
            const parts = st.map((e) => ({ pos: e.slot, tok: `${e.slot}:${prev[e.type][j - 1][e.k]}` }));
            // A zigzag along the seam between two children (A B A B ...) is one run: keep its
            // first two and last two pieces, and the run's parity, not its length.
            const out: string[] = [];
            let i = 0;
            while (i < parts.length) {
              let e = i + 1;
              if (collapse) while (e < parts.length && parts[e].pos === parts[e - 2 < i ? i : e - 2]?.pos && e - i >= 2) e++;
              if (collapse && e - i < 3) {
                // extend an alternating run of two slots
                e = i + 1;
                while (e < parts.length && (e - i < 2 ? parts[e].pos !== parts[i].pos : parts[e].pos === parts[e - 2].pos)) e++;
              }
              const run = parts.slice(i, e);
              if (collapse && run.length >= 4) out.push(`run[${run[0].tok}|${run[1].tok}|${run[run.length - 2].tok}|${run[run.length - 1].tok}|${run.length % 2}]`);
              else out.push(...run.map((r) => r.tok));
              i = e;
            }
            sig[j][k] = intern(j, `${t}|${out.join(',')}`);
          }
        }
      }
      next[t] = sig;
      for (const k of L.crossings()) {
        const m = L.mate(k);
        if (m < 0 || m < k || L.len(k) < minLength) continue;
        arcs++;
        for (let j = 0; j <= maxDepth; j++) {
          // Canonical over direction: the smaller of the two directed ids is not comparable across directions,
          // so use the unordered pair.
          const a = sig[j][k];
          const b = sig[j][m];
          counts[j].add(intern(j, `pair|${Math.min(a, b)}|${Math.max(a, b)}`));
        }
      }
    }
    rows.push({ level: n, counts: counts.map((s) => s.size), arcs });
    prev = next;
  }
  return rows;
}

if (process.argv[1]?.endsWith('arc-grammar.ts')) {
  const [family, rule, combo, lvArg, depthArg, minArg, mode] = process.argv.slice(2);
  const maxLevel = Number(lvArg);
  const maxDepth = Number(depthArg ?? 4);
  const minLength = Number(minArg ?? 1);
  const cs = new CircuitShapes(family as TileFamilyId, [...rule].map(Number), [...combo].map((ch) => parseInt(ch, 36)), maxLevel, 1e18);
  const rows = arcSignatureCounts(cs, maxDepth, minLength, mode === 'runs');
  console.log(`${family} ${rule}-${combo}: distinct arc signatures (arcs of ${minLength}+ tiles), by level; columns are depth 0..${maxDepth}`);
  for (const r of rows) console.log(`  L${r.level}: ${r.arcs} arcs; ${r.counts.map((c, j) => (j <= r.level ? String(c) : '-')).join('  ')}`);
}
